'use strict';
const reviewLabels={ready:'Pronta para conferir',waiting:'Aguardando informação',completed:'Conferência concluída',changed:'Dados alterados — conferir novamente',needs_changes:'Correção solicitada',cancelled:'Aula cancelada'};
let reviewQueueGeneration=0,reviewDetailGeneration=0,reviewChosen='';
const reviewDate=value=>new Date(value).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});
function reviewCheck(form,label,name){const wrap=el('label',undefined,{class:'check-label'}),input=el('input',undefined,{type:'checkbox',name,required:''});wrap.append(input,document.createTextNode(label));form.append(wrap);return input;}
async function loadClassReviews(){
 if(!['admin','secretary'].includes(me?.role)||!$('class-review-area'))return;
 const generation=++reviewQueueGeneration,unit=$('review-unit').value,from=$('review-from').value,to=$('review-to').value;
 const p=await api('/class-reviews?'+new URLSearchParams({unit,from,to}));if(generation!==reviewQueueGeneration||!$('review-list')||!me)return;
 const list=$('review-list'),filter=$('review-filter').value;list.replaceChildren();$('review-overview').replaceChildren(el('p',p.summary.pending+' tarefa(s) pendente(s) · '+p.summary.completed+' concluída(s) · '+p.summary.cancelled+' aula(s) cancelada(s)',{role:'status'}));
 const n=p.notifications;$('review-overview').append(el('p',n.configured?'Email diário a partir das 8h (Brasília) para: '+(n.recipients.join(', ')||'nenhuma secretaria atribuída')+'. Verificação automática a cada cinco minutos.':'Aviso por email ainda não configurado.',{class:'muted'}));if(n.states)$('review-overview').append(el('p',(n.states.accepted||0)+' aviso(s) aceito(s) pelo serviço de email · '+(n.states.pending||0)+' aguardando · '+((n.states.failed||0)+(n.states.uncertain||0))+' para conferir. Aceitação não comprova entrega ou leitura.',{class:'muted'}));
 let shown=0;for(const task of p.tasks){if(filter==='pending'&&['completed','cancelled'].includes(task.status)||filter==='completed'&&task.status!=='completed')continue;shown++;
  const button=el('button',task.lesson.day.split('-').reverse().join('/')+' · '+classUnits[task.lesson.unit]+' · '+task.lesson.time+' · '+task.lesson.label+' — '+reviewLabels[task.status],{type:'button',class:'secondary review-task-button'});button.addEventListener('click',action(()=>openClassReview(task.lesson.id)));list.append(button);
 }if(!shown)list.append(el('p','Nenhuma tarefa neste filtro e período. As aulas com chamada aberta entram automaticamente nesta lista.'));
 let banner=$('class-review-banner');if(!banner){banner=el('aside',undefined,{id:'class-review-banner',class:'class-review-banner','aria-label':'Conferências das aulas'});$('workspace-nav-shell').before(banner)}banner.hidden=!p.summary.pending;banner.replaceChildren();if(p.summary.pending){banner.append(el('strong',p.summary.pending+' aula(s) aguardam conferência no período selecionado'),el('p','Secretaria: conferir foto, chamada e resumo da aula.'));const b=el('button','Abrir conferências das aulas',{type:'button',class:'secondary'});b.addEventListener('click',()=>showPanel('class-review-area'));banner.append(b)}
}
async function openClassReview(id){
 const generation=++reviewDetailGeneration;reviewChosen=id;const p=await api('/class-reviews/'+id),box=$('review-detail');if(!box||generation!==reviewDetailGeneration||!me)return;box.hidden=false;box.replaceChildren();delete box.dataset.dirty;
 const c=p.lesson,t=p.summary.counts;box.append(el('h3',c.label+' · '+c.day.split('-').reverse().join('/')+' · '+c.time),el('p',classUnits[c.unit]+' · '+reviewLabels[p.status],{role:'status'}));
 if(p.last_review)box.append(el('p','Última conferência: '+p.last_review.reviewed_by+' · '+reviewDate(p.last_review.reviewed_at)+(p.last_review.note?' · '+p.last_review.note:'')));
 if(p.status==='changed')box.append(el('p','Há mudanças desde o fechamento anterior. O histórico foi preservado. Confira novamente antes de concluir.',{role:'alert',class:'form-error'}));
 const photo=el('section',undefined,{class:'review-step'});photo.append(el('h4','1 · Conferir a foto'));box.append(photo);const photoBox=el('div');photo.append(photoBox);let photoLoaded=false;
 try{const {mountClassEvidence}=await import('./class-evidence.js');if(generation!==reviewDetailGeneration||!photoBox.isConnected)return;await mountClassEvidence({api,el,field,action:fn=>action(async event=>{await fn(event);if(generation===reviewDetailGeneration&&box.dataset.dirty!=='true'){await openClassReview(id);await loadClassReviews()}}),notice},photoBox,id,{allowUpload:false,reviewPendingOnly:true});photoLoaded=true;}catch(error){photoBox.append(el('p',error.message||'Não foi possível abrir a foto. Atualize a tarefa.',{class:'form-error',role:'alert'}));}
 if(generation!==reviewDetailGeneration||!box.isConnected)return;
 const attendance=el('section',undefined,{class:'review-step'});attendance.append(el('h4','2 · Conferir chamada e visitantes'),el('p',t.present+' presente(s) matriculado(s) · '+t.absent+' falta(s) · '+t.justified+' justificada(s) · '+t.unmarked+' sem marcação · '+t.visitors+' visitante(s) presente(s).'));
 const rows=el('details');rows.append(el('summary','Ver alunos e marcações ('+p.students.length+')'));for(const s of p.students)rows.append(el('p',s.name+' · '+s.id+' · '+attendanceNames[s.status]));for(const v of p.visitors)rows.append(el('p',v.name+' · Visitante · '+(v.present?'Presença registrada':'Presença desfeita')));attendance.append(rows);
 const go=el('button','Abrir chamada para conferir ou corrigir',{type:'button',class:'secondary'});go.addEventListener('click',action(async()=>{$('class-unit').value=c.unit;await loadAttendanceGroups();showPanel('attendance-area');await classDetail(id)}));attendance.append(go,el('p','Não marque faltas para encerrar uma pendência. Foto não identifica automaticamente os participantes. A secretaria de núcleo confere; correções na presença continuam restritas aos perfis autorizados.',{class:'muted'}));box.append(attendance);
 const final=el('section',undefined,{class:'review-step'});final.append(el('h4','3 · Conferir resumo e salvar'),el('p',t.total_present+' participação(ões): '+t.present+' de matriculados + '+t.visitors+' de visitantes. '+(p.summary.held?'Realização/presença registrada.':'Realização ainda não confirmada.')));
 const refresh=el('button','Atualizar esta tarefa após conferir foto ou chamada',{type:'button',class:'secondary'});refresh.addEventListener('click',action(()=>openClassReview(id)));final.append(refresh);
 if(p.reasons.length)final.append(el('p','Antes de concluir: '+p.reasons.join('; ')+'.',{class:'form-error',role:'status'}));
 if(!c.cancelled&&p.status!=='completed'){
  const form=el('form',undefined,{class:'class-review-form'});field(form,'Decisão da secretaria','decision','completed',{options:{completed:'Concluir conferência da aula',needs_changes:'Solicitar correção à equipe'}});
  const checks=[reviewCheck(form,'Conferi a foto desta aula.','photo_checked'),reviewCheck(form,'Conferi as marcações da chamada e os visitantes.','attendance_checked'),reviewCheck(form,'Conferi o resumo e as informações desta aula.','summary_checked')];
  const note=el('textarea','',{name:'note',id:'review-note',rows:'3',maxlength:'1500'});form.append(el('label','Observação ou correção necessária',{for:note.id}),note,el('p','Descreva divergências e a próxima ação. Não registre conteúdo clínico nem deduza presenças pela foto.',{class:'muted'}));
  const save=el('button','Salvar conferência completa');save.disabled=!!p.reasons.length||!photoLoaded;save.dataset.locked=String(save.disabled);form.append(save);
  const sync=()=>{const complete=form.elements.decision.value==='completed';checks.forEach(i=>i.required=complete);note.required=!complete;note.minLength=complete?0:5;save.disabled=complete&&(!!p.reasons.length||!photoLoaded);save.dataset.locked=String(save.disabled);save.textContent=complete?'Salvar conferência completa':'Registrar correção necessária'};form.elements.decision.addEventListener('change',sync);
  let requestId=crypto.randomUUID();form.addEventListener('input',()=>{requestId=crypto.randomUUID();box.dataset.dirty='true'});form.addEventListener('change',()=>{requestId=crypto.randomUUID();box.dataset.dirty='true'});
  form.addEventListener('submit',action(async()=>{const values=Object.fromEntries(new FormData(form));await api('/class-reviews/'+id,{method:'POST',data:{...values,id:requestId,version:p.version,fingerprint:p.fingerprint,photo_checked:checks[0].checked,attendance_checked:checks[1].checked,summary_checked:checks[2].checked}});delete box.dataset.dirty;await openClassReview(id);await loadClassReviews();notice('Conferência salva. O histórico identifica quem conferiu e quando.')}));final.append(form);
 }else final.append(el('p',c.cancelled?'Aula cancelada: não entra nos totais de realização. O histórico permanece disponível.':'Conferência completa salva. Esta aula saiu da lista de pendências.'));
 box.append(final);const history=el('details');history.append(el('summary','Histórico das conferências ('+p.history.length+')'));for(const h of p.history)history.append(el('p',reviewDate(h.created_at)+' · '+h.actor_name+' · '+(h.decision==='completed'?'Concluída':'Correção solicitada')),el('p',h.note||'Sem observação'),el('p','Resumo salvo: '+h.snapshot.counts.total_present+' participações · '+h.snapshot.counts.unmarked+' sem marcação'));box.append(history);box.scrollIntoView({block:'start'});
}
document.addEventListener('portal:loaded',action(async()=>{
 if(!['admin','secretary'].includes(me?.role))return;
 if(!$('class-review-area')){const area=el('section',undefined,{id:'class-review-area'});$('team-area').before(area);area.append(el('h2','Conferências das aulas'),el('p','Tarefa da secretaria: foto → chamada e visitantes → resumo e fechamento. Fotos aprovadas são preservadas; a conferência completa exige confirmação das três etapas.'));
 const filters=el('div',undefined,{class:'review-filters'});field(filters,'Núcleo das conferências','unit','',{options:{'':'Todos os núcleos autorizados',...scopeUnitNames()},htmlId:'review-unit'});field(filters,'De','from',new Date(Date.parse(todayBR()+'T12:00:00Z')-89*86400000).toISOString().slice(0,10),{type:'date',htmlId:'review-from'});field(filters,'Até','to',todayBR(),{type:'date',htmlId:'review-to'});field(filters,'Situação das tarefas','filter','pending',{options:{pending:'Pendentes',completed:'Concluídas',all:'Todas, incluindo canceladas'},htmlId:'review-filter'});area.append(filters);
 for(const id of ['review-unit','review-from','review-to','review-filter'])$(id).addEventListener('change',action(async()=>{reviewDetailGeneration++;reviewChosen='';$('review-detail').hidden=true;await loadClassReviews()}));const b=el('button','Atualizar conferências',{type:'button',class:'secondary'});b.addEventListener('click',action(loadClassReviews));area.append(b,el('div',undefined,{id:'review-overview'}),el('div',undefined,{id:'review-list'}),el('section',undefined,{id:'review-detail',hidden:''}));
 }await loadClassReviews();
}));
document.addEventListener('portal:logout',()=>{reviewQueueGeneration++;reviewDetailGeneration++;reviewChosen='';$('class-review-area')?.remove();$('class-review-banner')?.remove()});
setInterval(()=>{if(me&&['admin','secretary'].includes(me.role)&&!document.hidden&&!document.querySelector('#review-detail .class-review-form')&&$('class-review-area'))loadClassReviews().catch(()=>{const box=$('review-overview');if(box&&!box.querySelector('.review-stale'))box.append(el('p','Não foi possível atualizar as tarefas. Use Atualizar conferências.',{role:'status',class:'form-error review-stale'}));});},30000);
window.addEventListener('beforeunload',event=>{if($('review-detail')?.dataset.dirty==='true'){event.preventDefault();event.returnValue=''}});
